def transform(grid):
    # Recolor uninterrupted full-width/full-height monochrome lines.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            out[r] = [2] * w
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1:
            for r in range(h):
                out[r][c] = 2
    return out

